#include <iostream>
using namespace std;

int main() {
    int n = 0;
    cin >> n;
    for (int i = 0; i < n; i++) {
        int v = 0;
        cin >> v;
        cout << v << " 是" << ((v & 1) ? "奇数" : "偶数") << endl;
    }
    return 0;
}
